// Package colorprofile used to force a lipgloss colour profile in tests.
//
// With lipgloss v2, Style.Render always emits the full-colour escape sequences:
// downsampling happens only when the output is written (lipgloss.Fprint, or the
// Bubble Tea renderer given tea.WithColorProfile). A test that renders a Style
// therefore sees the same bytes with or without a TTY, and there is nothing
// left to force. TrueColor and Force are kept as no-ops so the callers
// (internal/testutil users, TestMain) do not change.
package colorprofile

// TrueColor is a no-op under lipgloss v2 (see the package comment).
func TrueColor(t interface {
	Helper()
	Cleanup(func())
}) {
	t.Helper()
}

// Force is a no-op under lipgloss v2 and returns a no-op restore function.
func Force() (restore func()) { return func() {} }
EOF
