package testutil

import (
	"testing"

	tea "charm.land/bubbletea/v2"
)

type m1 struct{ n int }

func TestSpikeKeyStrings(t *testing.T) {
	for in, want := range map[string]string{
		"enter": "enter", "esc": "esc", "escape": "esc", "space": "space", " ": "space",
		"shift+tab": "shift+tab", "ctrl+c": "ctrl+c", "alt+:": "alt+:", "pgdown": "pgdown",
		"y": "y", "Y": "Y", "f5": "f5", "backspace": "backspace", "alt+enter": "alt+enter",
	} {
