		t.Errorf("paste text %q %v", s, ok)
	}
	if s, ok := Text(Key(" ")); !ok || s != " " {
		t.Errorf("space text %q %v", s, ok)
	}
}

func TestSpikeMsgsFlattensSequenceAndBatch(t *testing.T) {
	c := func(n int) tea.Cmd { return func() tea.Msg { return m1{n} } }
	seq := tea.Sequence(c(1), tea.Batch(c(2), c(3)), c(4))
	got := Msgs(seq)
