package app

import (
	"strings"
	"testing"

	"charm.land/bubbles/v2/viewport"

	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// Spike DEVDESK-198 criterion 8.
func TestSpikeViewportHorizontalKeys(t *testing.T) {
	wide := strings.Repeat("x", 300) + strings.Repeat("\n"+strings.Repeat("y", 300), 80)

	def := viewport.New(viewport.WithWidth(40), viewport.WithHeight(10))
	def.SetContent(wide)
	def, _ = def.Update(testutil.Key("right"))
	t.Logf("default KeyMap, right: XOffset=%d (soft wrap=%v)", def.XOffset(), def.SoftWrap)
	def, _ = def.Update(testutil.Key("l"))
	t.Logf("default KeyMap, l: XOffset=%d YOffset=%d", def.XOffset(), def.YOffset())
	def, _ = def.Update(testutil.Key("j"))
	t.Logf("default KeyMap, j: YOffset=%d", def.YOffset())

	vp := viewport.New(viewport.WithWidth(40), viewport.WithHeight(10))
	vp.KeyMap = arrowOnlyScroll()
	vp.SetContent(wide)
	for _, k := range []string{"left", "right", "h", "l", "j", "k", "space", "d", "u", "b", "f"} {
		vp, _ = vp.Update(testutil.Key(k))
		if vp.XOffset() != 0 || vp.YOffset() != 0 {
			t.Errorf("arrowOnlyScroll: key %q moved the viewport (x=%d y=%d)", k, vp.XOffset(), vp.YOffset())
		}
	}
	vp, _ = vp.Update(testutil.Key("down"))
	if vp.YOffset() != 1 {
		t.Errorf("down must still scroll, y=%d", vp.YOffset())
	}
	vp, _ = vp.Update(testutil.Key("pgdown"))
	if vp.YOffset() <= 1 {
		t.Errorf("pgdown must still scroll, y=%d", vp.YOffset())
	}
}
EOF
HOME=$(mktemp -d) GOMODCACHE=/home/anthoni/go/pkg/mod go test -v -run SpikeViewport ./internal/app 2>&1 | grep -v '^=== '

